package vn.codegym.repository;import vn.codegym.model.Product;import java.util.*;public class ProductRepository{private static final List<Product> data=new ArrayList<>(List.of(new Product(1,"Laptop",1500),new Product(2,"Keyboard",60)));public List<Product> findAll(){return data;}public Product find(int id){return data.stream().filter(p->p.getId()==id).findFirst().orElse(null);}public void add(String name,double price){int id=data.stream().mapToInt(Product::getId).max().orElse(0)+1;data.add(new Product(id,name,price));}public void update(int id,String name,double price){Product p=find(id);if(p!=null){p.setName(name);p.setPrice(price);}}public void delete(int id){data.removeIf(p->p.getId()==id);}}
